def _links(lang: str, labels: list[str]) -> list[tuple[str, str]]:
    hrefs = [
        f"/{lang}/medical-centers/cellular-therapy/",
        f"/{lang}/bone-marrow-transplant-turkey/",
        f"/{lang}/cancer-treatment-turkey/",
        f"/{lang}/patient-journey/",
        f"/{lang}/faq/",
        f"/{lang}/check-up/",
        f"/{lang}/contact/",
    ]
    return list(zip(hrefs, labels))


